def compute(vars):
    try:
        percentage = vars["v1"] / vars["v2"] * 100
    except ZeroDivisionError:
        return None

    return {
        "value": percentage,
        "trace": {
            "remaining_authorized_repurchase_capacity": vars["v1"],
            "authorized_repurchase_capacity": vars["v2"],
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
